import{_ as r,c as a,o,aM as t}from"./chunks/framework.kKeYZnSg.js";const l="/fe-handbook/assets/4-1.ad156d1c.CXWdTkKS.png",n="/fe-handbook/assets/error.BdKcgnfd.gif",u=JSON.parse('{"title":"微信小程序","description":"","frontmatter":{},"headers":[],"relativePath":"framework/wxmp/miniprogram/index.md","filePath":"framework/wxmp/miniprogram/index.md","lastUpdated":1785398145000}'),i={name:"framework/wxmp/miniprogram/index.md"};function s(p,e,h,d,c,m){return o(),a("div",null,e[0]||(e[0]=[t('<h1 id="微信小程序" tabindex="-1"><a href="https://developers.weixin.qq.com/miniprogram/dev/framework/" target="_blank" rel="nofollow noopener noreferrer">微信小程序</a> <a class="header-anchor" href="#微信小程序" aria-label="Permalink to &quot;[微信小程序](https://developers.weixin.qq.com/miniprogram/dev/framework/)&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><blockquote><p>当微信中的 WebView 逐渐成为移动 Web 的一个重要入口时，微信就有相关的 JS API 了。JS-SDK 解决了移动【<strong>网页能力不足</strong>】的问题，通过暴露微信的接口使得 Web 开发者能够拥有更多的能力，然而在更多的能力之外，JS-SDK 的模式并没有解决使用移动网页遇到的体验不良的问题。用户在访问网页的时候，在浏览器开始显示之前都会有一个【白屏】的过程，在移动端，受限于设备性能和网络速度，白屏会更加明显。</p></blockquote><h2 id="渲染层和逻辑层" tabindex="-1">渲染层和逻辑层 <a class="header-anchor" href="#渲染层和逻辑层" aria-label="Permalink to &quot;渲染层和逻辑层&quot;">​</a></h2><blockquote><p>小程序的运行环境分成渲染层和逻辑层，其中 WXML 模板和 WXSS 样式工作在渲染层，JS 脚本工作在逻辑层。</p><p>小程序的渲染层和逻辑层分别由2个线程管理：渲染层的界面使用了WebView 进行渲染；逻辑层采用JsCore线程运行JS脚本。一个小程序存在多个界面，所以渲染层存在多个WebView线程，这两个线程的通信会经由微信客户端（下文中也会采用Native来代指微信客户端）做中转，逻辑层发送网络请求也经由Native转发，小程序的通信模型下图所示。</p></blockquote><p><img src="'+l+'" alt="img"></p><h2 id="渲染模式" tabindex="-1">渲染模式 <a class="header-anchor" href="#渲染模式" aria-label="Permalink to &quot;渲染模式&quot;">​</a></h2><ul><li>WebView</li><li>Skyline</li></ul><h2 id="skyline" tabindex="-1">Skyline <a class="header-anchor" href="#skyline" aria-label="Permalink to &quot;Skyline&quot;">​</a></h2><p>小程序新一代原生渲染引擎</p><p>文档地址：<a href="https://developers.weixin.qq.com/miniprogram/dev/framework/" target="_blank" rel="nofollow noopener noreferrer">https://developers.weixin.qq.com/miniprogram/dev/framework/</a> 官方文档指南和框架的两个地址配反了。。。</p><p><img src="'+n+'" alt="error"></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><ul><li>滚动穿透，参考<a href="https://developers.weixin.qq.com/community/develop/article/doc/00062666530a300ed35ba552856413" target="_blank" rel="nofollow noopener noreferrer">社区问答</a>，<a href="https://www.zhihu.com/question/52852717" target="_blank" rel="nofollow noopener noreferrer">知乎回答</a></li></ul><h2 id="开源工具" tabindex="-1">开源工具 <a class="header-anchor" href="#开源工具" aria-label="Permalink to &quot;开源工具&quot;">​</a></h2><ul><li><a href="https://github.com/wxp-ui/wxp-ui" target="_blank" rel="nofollow noopener noreferrer">https://github.com/wxp-ui/wxp-ui</a></li></ul><h2 id="donut" tabindex="-1">Donut <a class="header-anchor" href="#donut" aria-label="Permalink to &quot;Donut&quot;">​</a></h2><ul><li>文档：<a href="https://dev.weixin.qq.com/docs/" target="_blank" rel="nofollow noopener noreferrer">https://dev.weixin.qq.com/docs/</a></li><li></li></ul><h2 id="跨端" tabindex="-1">跨端 <a class="header-anchor" href="#跨端" aria-label="Permalink to &quot;跨端&quot;">​</a></h2><ul><li><a href="https://uniapp.dcloud.io/" target="_blank" rel="nofollow noopener noreferrer">Uniapp</a></li><li><a href="https://docs.taro.zone/docs/" target="_blank" rel="nofollow noopener noreferrer">Taro</a></li><li><a href="https://mpxjs.cn/" target="_blank" rel="nofollow noopener noreferrer">MPX</a></li></ul>',20)]))}const b=r(i,[["render",s]]);export{u as __pageData,b as default};
